/* @lc app=leetcode id=2577 lang=kotlin */ class Solution { fun minimumTime(grid: Array<IntArray>): Int = if (grid[0][1] > 1 && grid[1][0] > 1) -1 else java.util.PriorityQueue<IntArray>(compareBy { it[0] }).apply { add(intArrayOf(0, 0, 0)) }.let { pq -> BooleanArray(grid.size * grid[0].size).let { vis -> generateSequence { pq.poll() }.map { curr -> if (curr[1] == grid.size - 1 && curr[2] == grid[0].size - 1) curr[0] else if (vis[curr[1] * grid[0].size + curr[2]]) -1 else vis.also { it[curr[1] * grid[0].size + curr[2]] = true }.run { intArrayOf(0, 1, 0, -1).zip(intArrayOf(1, 0, -1, 0)).forEach { (dr, dc) -> (curr[1] + dr to curr[2] + dc).let { (nr, nc) -> if (nr in grid.indices && nc in grid[0].indices && !vis[nr * grid[0].size + nc]) pq.add(intArrayOf(maxOf(curr[0] + 1, grid[nr][nc] + if ((grid[nr][nc] - curr[0]) % 2 == 0) 1 else 0), nr, nc)) } } }.run { -1 } }.filter { it != -1 }.first() } } }